import heapq
from collections import defaultdict

def toposort(nodes, edges):
    # Ensure we do not modify the input lists
    nodes_set = set(nodes)
    if len(nodes_set) != len(nodes):
        raise ValueError("Nodes list contains duplicates")

    # Build adjacency sets, checking for self-loops
    adjacency = {n: set() for n in nodes}
    for src, dst in edges:
        if src == dst:
            raise ValueError("Self-loop detected")
        adjacency[src].add(dst)

    # Compute indegree for each node
    indegree = {n: 0 for n in nodes}
    for src, dests in adjacency.items():
        for dst in dests:
            indegree[dst] += 1

    # Initialize min-heap with nodes having zero indegree
    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nxt in adjacency[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    result = []
    cur = []
    cur_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if cur_sum + weight <= limit:
            cur.append(name)
            cur_sum += weight
        else:
            if cur:
                result.append(cur)
            cur = [name]
            cur_sum = weight

    if cur:
        result.append(cur)

    return result

def parse_sse(chunks):
    import codecs

    decoder = codecs.getincrementaldecoder("utf-8")()
    text_buffer = ""
    results = []
    data_lines = []

    def _dispatch():
        nonlocal data_lines, results
        if data_lines:
            event = "\n".join(data_lines)
            if event == "[DONE]":
                return True  # stop parsing
            results.append(event)
        data_lines = []

    stopped = False

    for chunk in chunks:
        if stopped:
            break
        decoded = decoder.decode(chunk, final=False)
        text_buffer += decoded

        while True:
            idx = text_buffer.find("\n")
            if idx == -1:
                break
            line = text_buffer[:idx]
            text_buffer = text_buffer[idx + 1 :]
            if line.endswith("\r"):
                line = line[:-1]

            if line == "":
                if _dispatch():
                    stopped = True
                    break
                continue

            if line.startswith("data:"):
                value = line[5:]
                if value.startswith(" "):
                    value = value[1:]
                data_lines.append(value)

    if not stopped:
        # Flush remaining decoder output
        text_buffer += decoder.decode(b"", final=True)
        while True:
            idx = text_buffer.find("\n")
            if idx == -1:
                break
            line = text_buffer[:idx]
            text_buffer = text_buffer[idx + 1 :]
            if line.endswith("\r"):
                line = line[:-1]

            if line == "":
                _dispatch()
                continue

            if line.startswith("data:"):
                value = line[5:]
                if value.startswith(" "):
                    value = value[1:]
                data_lines.append(value)

    return results

import math

def retry_delay(attempt: int, base: float, cap: float) -> float:
    """
    Compute a retry delay of the form min(cap, base * 2**attempt).

    Parameters:
        attempt (int): Non‑negative integer indicating the retry attempt.
        base (float): Non‑negative, finite floating point number.
        cap (float): Non‑negative, finite floating point number.

    Returns:
        float: The computed delay.

    Raises:
        ValueError: If any argument is negative, not an integer (for attempt),
                    or not finite (for base or cap).
    """
    # Validate inputs
    if not isinstance(attempt, int) or attempt < 0:
        raise ValueError("attempt must be a non‑negative integer")
    if not (math.isfinite(base) and base >= 0):
        raise ValueError("base must be a non‑negative finite number")
    if not (math.isfinite(cap) and cap >= 0):
        raise ValueError("cap must be a non‑negative finite number")

    # Handle trivial cases
    if cap == 0 or base == 0:
        return float(cap if cap == 0 else 0.0)
    if base >= cap:
        return float(cap)

    # Compute the largest exponent e such that base * 2**e <= cap
    # Using log2 to avoid overflow
    max_exp = math.log2(cap) - math.log2(base)

    if attempt <= max_exp:
        # Safe to compute directly; result is <= cap
        return float(math.ldexp(base, attempt))
    else:
        return float(cap)
